const collapsedRequirements=new Set();
function hierarchyRows(){return backlog().rows.map(r=>{r.parentId??=null;r.priorityPoints??=({High:80,Medium:50,Low:20}[r.priority]||50);r.storyStatus??='Draft';return r;});}
function childRequirements(parent=null){return hierarchyRows().filter(r=>r.parentId===parent).sort((a,b)=>b.priorityPoints-a.priorityPoints||a.id.localeCompare(b.id));}
function approvedRequirements(){return hierarchyRows().filter(r=>r.status==='Approved');}
function eligibleTests(){return approvedRequirements();}
function invalidateRequirement(r){r.status='Draft';r.storyStatus='Draft';delete testStatuses[selected+'-'+r.id];backlog().approved=false;}
function setRequirementPoints(id,value){const n=Number(value),r=hierarchyRows().find(r=>r.id===id);if(!r||!Number.isInteger(n)||n<0||n>100)return toast('Enter priority points from 0 to 100.');r.priorityPoints=n;render();}
function toggleRequirement(id){const key=selected+':'+id;collapsedRequirements.has(key)?collapsedRequirements.delete(key):collapsedRequirements.add(key);render();}
function approveRequirement(id){const r=hierarchyRows().find(r=>r.id===id);if(r){r.status='Approved';render();}}
function requirementTreeRows(parent=null,depth=0){return childRequirements(parent).map(r=>{const children=childRequirements(r.id),closed=collapsedRequirements.has(selected+':'+r.id);return '<tr><td><div class="requirement-name" style="padding-left:'+depth*22+'px">'+(children.length?'<button class="tree-toggle" aria-label="Toggle '+esc(r.story)+'" aria-expanded="'+!closed+'" onclick="toggleRequirement(\''+r.id+'\')">'+(closed?'›':'⌄')+'</button>':'<span class="tree-leaf">·</span>')+'<div><small>'+r.id+'</small><strong>'+esc(r.story)+'</strong></div></div></td><td>'+esc(r.module)+'</td><td><input class="priority-points" type="number" min="0" max="100" step="1" aria-label="Priority points for '+r.id+'" value="'+r.priorityPoints+'" onchange="setRequirementPoints(\''+r.id+'\',this.value)"></td><td>'+badge(r.status||'Draft')+'</td><td><div class="tree-row-actions">'+button('Edit',"editRequirement('"+r.id+"')")+button('+ Sub',"editRequirement('', '"+r.id+"')")+button('Tree',"showRequirementTree('"+r.id+"')")+(r.status!=='Approved'?button('Approve',"approveRequirement('"+r.id+"')"):'')+'</div></td></tr>'+(!closed?requirementTreeRows(r.id,depth+1):'');}).join('');}
blueprintPageRoutes.requirements=function(){return appNav()+bpHeading('Requirements management','Higher priority points appear first within each level. Approve requirements before writing their stories.',button('Tree map','showRequirementTree()')+button('+ Add requirement','editRequirement()',true)+button('Export requirements · Excel','openRequirementsExport()')+button('Continue to user stories →',"navigate('stories')",true))+'<section class="panel requirement-table"><table><thead><tr><th>Requirement hierarchy</th><th>Module</th><th>Priority points</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+requirementTreeRows()+'</tbody></table>'+(!hierarchyRows().length?'<div class="empty">Add your first requirement.</div>':'')+'</section>';};
editRequirement=function(id='',parentId=null){const rows=hierarchyRows(),r=rows.find(r=>r.id===id);const descendants=new Set([id]);let changed=true;while(changed){changed=false;rows.forEach(x=>{if(descendants.has(x.parentId)&&!descendants.has(x.id)){descendants.add(x.id);changed=true;}});}creationPage={title:r?'Edit requirement':'Add requirement',back:'requirements',body:assistedField('Requirement name','story',r?.story||'','draftRequirementFields')+field('Module','module',r?.module||'General')+'<label class="field">Parent requirement<select name="parentId"><option value="">Top-level requirement</option>'+rows.filter(x=>!descendants.has(x.id)).map(x=>'<option value="'+x.id+'" '+(x.id===(r?.parentId||parentId)?'selected':'')+'>'+esc(x.id+' · '+x.story)+'</option>').join('')+'</select></label><label class="field">Priority points (0–100)<input name="points" type="number" min="0" max="100" step="1" required value="'+(r?.priorityPoints??50)+'"></label><p class="sub">New or edited requirements need approval before progressing.</p>',submit:"saveRequirement(event,'"+id+"')"};navigate('create');};
saveRequirement=function(e,id){e.preventDefault();const f=new FormData(e.target),rows=hierarchyRows(),name=String(f.get('story')||'').trim(),points=Number(f.get('points')),parentId=String(f.get('parentId')||'')||null;if(!name||!Number.isInteger(points)||points<0||points>100)return toast('Enter a name and priority points from 0 to 100.');let ancestor=parentId,seen=new Set();while(ancestor){if(ancestor===id||seen.has(ancestor))return toast('A requirement cannot be its own ancestor.');seen.add(ancestor);const p=rows.find(x=>x.id===ancestor);if(!p)return toast('Select a valid parent.');ancestor=p.parentId;}let r=rows.find(x=>x.id===id);if(!r){r={id:'REQ-'+String(Math.max(0,...rows.map(x=>Number(x.id.replace('REQ-',''))||0))+1).padStart(3,'0'),ac:'',userStory:'',hours:0};backlog().rows.push(r);}Object.assign(r,{story:name,module:String(f.get('module')||'General'),priorityPoints:points,parentId,priority:points>=70?'High':points>=40?'Medium':'Low'});invalidateRequirement(r);navigate('requirements');};
function mapNode(r,withStories=false){return '<li><div class="map-node"><small>'+r.id+' · '+r.priorityPoints+' points · '+esc(r.status)+'</small><strong>'+esc(r.story)+'</strong></div>'+((withStories&&r.userStory)||childRequirements(r.id).length?'<ul>'+(withStories&&r.userStory?'<li><div class="map-node story-node"><small>User story · '+esc(r.storyStatus)+'</small>'+esc(r.userStory)+'</div><ul>'+r.ac.split(/\n+/).filter(x=>x.trim()).map(ac=>'<li><div class="map-node criteria-node"><small>Acceptance criterion</small>'+esc(ac)+'</div></li>').join('')+'</ul></li>':'')+childRequirements(r.id).map(x=>mapNode(x,withStories)).join('')+'</ul>':'')+'</li>';}
function showRequirementTree(id,withStories=false){const box=document.getElementById('modal'),rows=id?hierarchyRows().filter(r=>r.id===id):childRequirements();box.className='requirement-map-dialog';box.innerHTML='<div class="history-heading"><div><h2>'+(withStories?'Requirements, stories & acceptance criteria':'Requirement tree map')+'</h2><p class="sub">Parent → sub-requirement → nested sub-requirement</p></div><button aria-label="Close" onclick="document.getElementById(\'modal\').close()">×</button></div><div class="requirement-map"><ul>'+rows.map(r=>mapNode(r,withStories)).join('')+'</ul></div>';box.showModal();}
editStory=function(id){const rows=approvedRequirements(),r=rows.find(x=>x.id===id);if(!rows.length)return toast('Approve a requirement first.');creationPage={title:r?'Edit user story':'Add user story',back:'stories',body:'<label class="field">Approved requirement<select name="requirement" required>'+rows.map(x=>'<option value="'+x.id+'" '+(x.id===id?'selected':'')+'>'+esc(x.id+' · '+x.story)+'</option>').join('')+'</select></label>'+assistedField('User story','userStory',r?.userStory||'','draftStoryFields',true)+'<label class="field">Acceptance criteria<textarea name="acceptance" required>'+esc(r?.ac||'')+'</textarea></label><p class="sub">Stories are available after requirement approval. No separate story approval is needed.</p>',submit:'saveStory(event)'};navigate('create');};
saveStory=function(e){e.preventDefault();const f=new FormData(e.target),r=approvedRequirements().find(x=>x.id===f.get('requirement'));if(!r)return toast('The requirement must be approved first.');const story=String(f.get('userStory')||'').trim(),ac=String(f.get('acceptance')||'').trim();if(!story||!ac)return toast('Complete the story and acceptance criteria.');r.userStory=story;r.ac=ac;r.storyStatus='Draft';delete testStatuses[selected+'-'+r.id];navigate('stories');};
function approveStory(id){const r=approvedRequirements().find(x=>x.id===id);if(!r||!r.userStory?.trim()||!r.ac?.trim())return toast('Complete the story and criteria before approval.');r.storyStatus='Approved';render();}
blueprintPageRoutes.stories=function(){const rows=approvedRequirements().sort((a,b)=>b.priorityPoints-a.priorityPoints);return appNav()+bpHeading('User stories & acceptance criteria','Only approved requirements appear here. Test cases use requirement approval; stories do not need separate approval.',button('Tree map','showRequirementTree(undefined,true)')+button('+ Add story','editStory()',true)+button('Generate timeline →',"navigate('timeline')",true))+'<div class="story-list">'+rows.map(r=>'<section class="panel story-card"><b>'+esc(r.id+' · '+r.story)+'</b><h2>'+esc(r.userStory||'No user story added yet')+'</h2>'+badge(r.userStory?.trim()?'Saved':'Draft')+'<div class="acceptance"><b>Acceptance criteria</b><p style="white-space:pre-wrap">'+esc(r.ac||'Not defined yet')+'</p></div><div class="tree-row-actions">'+button('Edit story details',"editStory('"+r.id+"')")+button('Tree map',"showRequirementTree('"+r.id+"',true)")+'</div></section>').join('')+'</div>'+(!rows.length?'<section class="panel empty">Approve requirements in Requirements management to begin.</section>':'');};
blueprintPageRoutes.tests=function(){const rows=eligibleTests();return appNav()+bpHeading('Test cases','Only approved user stories and their acceptance criteria are included.',button('View quality assurance →',"navigate('quality')",true))+'<section class="panel">'+(rows.length?table(['Requirement','User story','Acceptance criteria / test','Outcome'],rows.map(r=>[esc(r.id+' · '+r.story),esc(r.userStory),esc(r.ac),'<select aria-label="Test outcome '+r.id+'" onchange="testStatuses[selected+\'-'+r.id+'\']=this.value">'+['Not run','Passed','Failed','Blocked'].map(s=>'<option '+((testStatuses[selected+'-'+r.id]||'Not run')===s?'selected':'')+'>'+s+'</option>').join('')+'</select>'])):'<div class="empty">Approve a user story to create its test case.</div>')+'</section>';};
qualityStats=function(){const rows=eligibleTests(),total=rows.length,passed=rows.filter(r=>testStatuses[selected+'-'+r.id]==='Passed').length,failed=rows.filter(r=>testStatuses[selected+'-'+r.id]==='Failed').length;return {total,passed,failed,score:total?Math.round(passed/total*100):0,coverage:total?100:0};};
blueprintPageRoutes.traceability=function(){
 if(!selected)return missingProject();
 const rows=hierarchyRows().slice().sort((a,b)=>b.priorityPoints-a.priorityPoints||a.id.localeCompare(b.id));
 const matrix=rows.map(r=>{const approved=r.status==='Approved',cases=approved?casesForRequirement(r):[],parent=rows.find(x=>x.id===r.parentId);return [
 '<strong>'+esc(r.id)+'</strong><span class="matrix-detail">'+esc(r.story)+'</span>'+(parent?'<small class="matrix-parent">'+esc(parent.id+' · '+parent.story)+'</small>':''),
 esc(r.module),badge(r.status),
 r.userStory?.trim()?'<span class="matrix-copy">'+esc(r.userStory)+'</span>':'<span class="badge gray">Not written</span>',
 r.ac?.trim()?'<span class="matrix-copy">'+esc(r.ac)+'</span>':'<span class="badge gray">Not defined</span>',
 !approved?'<span class="badge gray">Awaiting approval</span>':cases.length?cases.map(c=>'<div class="matrix-case"><strong>'+esc(c.id)+'</strong><span>'+esc(c.name)+'</span>'+badge(c.status||'Not run')+'</div>').join(''):'<span class="badge gray">No linked tests</span>'
 ];});
 return appNav()+bpHeading('Traceability matrix','Follow each requirement through its user story, acceptance criteria and test cases.')+'<section class="panel traceability-matrix"><div class="panel-title"><h2>Requirement links</h2><span class="badge blue">'+rows.length+'</span></div>'+table(['Requirement / Parent','Module','Approval','User story','Acceptance criteria','Linked test cases / Outcome'],matrix)+'</section>';
};
// Each eligible requirement owns independent test-case records.
const requirementTestCases={};
function casesForRequirement(r){const key=selected+':'+r.id;let group=requirementTestCases[key];const revision=JSON.stringify([r.story,r.userStory,r.ac]);if(!group){group=requirementTestCases[key]={revision,cases:demoCasesForRequirement(r)};}else if(group.revision!==revision){group.cases.forEach(c=>c.status='Not run');group.revision=revision;}return group.cases;}
function caseStatus(requirementId,caseId,status){const r=eligibleTests().find(x=>x.id===requirementId);if(!r)return;const c=casesForRequirement(r).find(x=>x.id===caseId);if(c&&['Not run','Passed','Failed','Blocked'].includes(status))c.status=status;}
function editTestCase(requirementId,caseId=''){const r=eligibleTests().find(x=>x.id===requirementId);if(!r)return toast('Approve the requirement first.');const c=casesForRequirement(r).find(x=>x.id===caseId);creationPage={title:c?'Edit test case':'Add test case',back:'tests',body:'<div class="notice">'+esc(r.id+' · '+r.story)+'</div>'+assistedField('Test case name','name',c?.name||'','draftTestCaseFields')+'<label class="field">Steps<textarea name="steps" required>'+esc(c?.steps||'')+'</textarea></label><label class="field">Expected result<textarea name="expected" required>'+esc(c?.expected||'')+'</textarea></label>',submit:"saveTestCase(event,'"+requirementId+"','"+caseId+"')"};navigate('create');}
function saveTestCase(event,requirementId,caseId){event.preventDefault();const r=eligibleTests().find(x=>x.id===requirementId);if(!r)return toast('Approve the requirement first.');const f=new FormData(event.target),name=String(f.get('name')||'').trim(),steps=String(f.get('steps')||'').trim(),expected=String(f.get('expected')||'').trim();if(!name||!steps||!expected)return toast('Complete the name, steps and expected result.');const cases=casesForRequirement(r),existing=cases.find(c=>c.id===caseId);if(existing)Object.assign(existing,{name,steps,expected,status:'Not run'});else cases.push({id:'TC-'+r.id.replace('REQ-','')+'-'+String(cases.length+1).padStart(2,'0'),name,steps,expected,status:'Not run'});navigate('tests');}
blueprintPageRoutes.tests=function(){const rows=eligibleTests();return appNav()+bpHeading('Test cases','Test drafts are created automatically for approved requirements. Demo generation — review before running.',button('View quality assurance →',"navigate('quality')",true))+rows.map(r=>{const cases=casesForRequirement(r);return '<section class="panel requirement-test-group"><div class="panel-title"><div><small>'+r.id+'</small><h2>'+esc(r.story)+'</h2><span class="sub">'+cases.length+' test cases</span></div>'+button('+ Add test case',"editTestCase('"+r.id+"')",true)+'</div>'+(cases.length?'<div class="requirement-table">'+table(['Test case','Steps','Expected result','Outcome',''],cases.map(c=>['<small>'+c.id+'</small><strong style="display:block">'+esc(c.name)+'</strong>','<span style="white-space:pre-wrap">'+esc(c.steps)+'</span>','<span style="white-space:pre-wrap">'+esc(c.expected)+'</span>','<select aria-label="Outcome for '+c.id+'" onchange="caseStatus(\''+r.id+'\',\''+c.id+'\',this.value)">'+['Not run','Passed','Failed','Blocked'].map(s=>'<option '+(c.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select>',button('Edit',"editTestCase('"+r.id+"','"+c.id+"')")]))+'</div>':'<div class="empty">No test cases yet. Add separate cases for successful actions, invalid input and other expected behavior.</div>')+'</section>';}).join('')+(!rows.length?'<section class="panel empty">Approve a requirement to create its test cases.</section>':'');};
qualityStats=function(){const rows=eligibleTests(),cases=rows.flatMap(r=>casesForRequirement(r)),total=cases.length,passed=cases.filter(c=>c.status==='Passed').length,failed=cases.filter(c=>c.status==='Failed').length;return {total,passed,failed,score:total?Math.round(passed/total*100):0,coverage:rows.length?Math.round(rows.filter(r=>casesForRequirement(r).length).length/rows.length*100):0};};
const caseQualityPage=blueprintPageRoutes.quality;
blueprintPageRoutes.quality=function(){return caseQualityPage().replace('Acceptance criteria coverage','Requirements test coverage').replace('Requirements with written criteria','Approved requirements with at least one test case');};
const invalidateBeforeCases=invalidateRequirement;
invalidateRequirement=function(r){invalidateBeforeCases(r);const group=requirementTestCases[selected+':'+r.id];if(group)group.cases.forEach(c=>c.status='Not run');};
function demoCasesForRequirement(r){
 const criteria=(r.ac||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);
 const definitions=criteria.length?criteria.map((ac,i)=>({name:r.story+' — acceptance '+(i+1),steps:'1. Prepare the preconditions for '+r.story+'.\n2. Perform the action described by this criterion:\n'+ac+'\n3. Compare the observed outcome with the expected result.',expected:ac})):[{name:r.story+' — successful action',steps:'1. Sign in as an authorized user.\n2. Open '+r.module+'.\n3. Perform '+r.story+' with valid input.',expected:'The requested action completes and the expected result is shown. Confirm the exact outcome against the requirement.'}];
 definitions.push({name:r.story+' — invalid input',steps:'1. Open '+r.module+'.\n2. Attempt '+r.story+' with missing or invalid input.',expected:'A clear validation error is shown and no invalid changes are saved. Confirm applicability during review.'});
 return definitions.map((c,i)=>({...c,id:'TC-'+r.id.replace('REQ-','')+'-'+String(i+1).padStart(2,'0'),status:'Not run',source:'Demo generation'}));
}
function draftTestCaseFields(){const form=document.querySelector('.creation-layout form');if(!form)return;const name=form.querySelector('[name="name"]'),steps=form.querySelector('[name="steps"]'),expected=form.querySelector('[name="expected"]');const prompt=name.value.trim();if(!prompt)return toast('Describe the test in the test case name field first.');const match=creationPage.submit.match(/saveTestCase\(event,'([^']+)'/),r=eligibleTests().find(x=>x.id===match?.[1]);if(!r)return toast('Select an approved requirement.');name.value=prompt.replace(/^(please |i want |we need )/i,'').replace(/^./,c=>c.toUpperCase());steps.value='1. Prepare '+r.module+' for testing.\n2. For '+r.story+', perform: '+prompt+'.\n3. Observe and record the result.';expected.value=/invalid|missing|error|denied/i.test(prompt)?'The invalid action is rejected with a clear message and no unintended changes are saved.':r.ac?.trim()||'The action completes as specified in '+r.id+'. Confirm the measurable outcome before running this test.';toast('Demo test draft filled. Review the steps and expected result.');}

Object.assign(localizedLabels,{'Traceability matrix':'トレーサビリティマトリクス','Follow each requirement through its user story, acceptance criteria and test cases.':'各要件とユーザーストーリー、受入基準、テストケースの関連を確認します。','Requirement links':'要件の関連','Requirement / Parent':'要件 / 親要件','Approval':'承認','Linked test cases / Outcome':'関連テストケース / 結果','No linked tests':'関連テストなし','Not defined':'未定義','Not written':'未作成','Awaiting approval':'承認待ち'});
